export function ThinkingOrbsGallery({
    selected,
    onSelect,
    columns = 0,
    ball = GALLERY_BALL,
    height = GALLERY_HEIGHT,
    showsLabel = true,
    speed = SPEED,
    reverse = REVERSE,
    startAt = START_AT,
    dotScale = DOT_SCALE,
    dots = KNOBS.n,
    spread = KNOBS.sp,
    perspective = KNOBS.pv,
    depthSize = KNOBS.dz,
    depthFade = KNOBS.df,
    dotOpacity = KNOBS.op,
    spin = KNOBS.sn,
    turn = KNOBS.yw / (Math.PI / 180),
    tilt = KNOBS.pc / (Math.PI / 180),
    scheme = SCHEME,
    accent = ACCENT_COLOR,
    dotColor = INK_DARK.dot,
    pill: pillDark = INK_DARK.pill,
    labelColor = INK_DARK.label,
    dotColorLight = INK_LIGHT.dot,
    pillLight = INK_LIGHT.pill,
    labelColorLight = INK_LIGHT.label,
    className,
    containerStyle,
}: ThinkingOrbsGalleryProps) {
    const isDark = useOrbDark(scheme);
    const ink = isDark ? dotColor : dotColorLight;
    const pill = isDark ? pillDark : pillLight;
    const labelInk = isDark ? labelColor : labelColorLight;
    const canvasRef = useRef<HTMLCanvasElement | null>(null);
    const scrollRef = useRef<HTMLDivElement | null>(null);
    const timerRef = useRef<number>(0);
    const [error, setError] = useState<string | null>(null);
    const [width, setWidth] = useState(720);
    const [own, setOwn] = useState(LOOP_ID);
    const [copied, setCopied] = useState<string | null>(null);

    const active = selected === undefined ? own : selected;
    const live = useMemo(() => STYLES.findIndex((s: any) => s.id === active), [active]);
    const layout = useMemo(
        () => galleryLayout(width, STYLES.length, ball, columns, showsLabel),
        [width, ball, columns, showsLabel],
    );

    const settings = useRef<any>(null);
    settings.current = {
        styles: STYLES,
        layout,
        live,
        scroller: null,
        speed,
        reverse,
        startAt,
        dotScale,
        knobs: {
            n: dots,
            sp: spread,
            pv: perspective,
            dz: depthSize,
            df: depthFade,
            yw: turn * (Math.PI / 180),
            pc: tilt * (Math.PI / 180),
            sn: spin,
            op: dotOpacity,
        },
        dot: useMemo(() => orbInk(ink), [ink]),
        accent: useMemo(() => orbInk(accent), [accent]),
    };

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        return startGallery(canvas, () => {
            const s = settings.current;
            s.scroller = scrollRef.current;
            return s;
        }, setError);
    }, []);

    useEffect(() => {
        const el = scrollRef.current;
        if (!el) return;
        const read = () => setWidth(el.clientWidth || 720);
        read();
        if (typeof ResizeObserver === "undefined") {
            window.addEventListener("resize", read);
            return () => window.removeEventListener("resize", read);
        }
        const ro = new ResizeObserver(read);
        ro.observe(el);
        return () => ro.disconnect();
    }, []);

    useEffect(() => () => {
        if (timerRef.current) window.clearTimeout(timerRef.current);
    }, []);

    const choose = (id: string) => {
        if (selected === undefined) setOwn(id);
        if (onSelect) onSelect(id);
        if (orbCopy(GALLERY_LINE + id + '" />')) {
            setCopied(id);
            if (timerRef.current) window.clearTimeout(timerRef.current);
            timerRef.current = window.setTimeout(() => setCopied(null), COPIED_MS);
        }
    };

    const hair = orbAlpha(labelInk, 0.08);

    return (
        <div
            className={className}
            style={{ position: "relative", width: "100%", height, ...containerStyle }}
        >
            <canvas
                ref={canvasRef}
                style={{
                    position: "absolute", top: 0, left: 0, width: "100%", height: "100%",
                    display: "block", pointerEvents: "none", background: "transparent",
                    zIndex: 1,
                }}
            />
            <div
                ref={scrollRef}
                style={{
                    position: "absolute", top: 0, left: 0, right: 0, bottom: 0,
                    overflowY: "auto", overflowX: "hidden", scrollbarGutter: "stable",
                }}
            >
                {error ? (
                    <div style={{
                        margin: 12, padding: "12px 14px", borderRadius: 12,
                        background: pill, color: "#8f959c", font: "13px " + FONT,
                    }}>
                        {error}
                    </div>
                ) : null}
                <div style={{ position: "relative", width: layout.width, height: layout.height }}>
                    {STYLES.map((s: any, i: number) => {
                        const on = s.id === active;
                        return (
                            <button
                                key={s.id}
                                type="button"
                                title={s.motion}
                                onClick={() => choose(s.id)}
                                style={{
                                    position: "absolute",
                                    left: layout.x(i),
                                    top: layout.y(i),
                                    width: layout.cellW,
                                    height: layout.cellH,
                                    boxSizing: "border-box",
                                    margin: 0,
                                    padding: 0,
                                    background: pill,
                                    border: "1px solid " + (on ? "transparent" : hair),
                                    boxShadow: on ? "inset 0 0 0 var(--tri-border) " + accent : "none",
                                    borderRadius: 14,
                                    cursor: "pointer",
                                    appearance: "none",
                                    WebkitAppearance: "none",
                                    color: labelInk,
                                    font: "inherit",
                                }}
                            >
                                {showsLabel ? (
                                    <span style={{
                                        position: "absolute", left: 0, right: 0, bottom: 9,
                                        padding: "0 6px",
                                        fontFamily: FONT, fontSize: 12, lineHeight: 1,
                                        whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis",
                                        color: on ? accent : labelInk,
                                        opacity: on ? 1 : LABEL_OPACITY * 0.85,
                                    }}>
                                        {copied === s.id ? "Copied" : s.name}
                                    </span>
                                ) : null}
                            </button>
                        );
                    })}
                </div>
            </div>
        </div>
    );
}

