              {others.length > 5 && (
                <span
                  className="grid size-[26px] place-items-center rounded-full bg-white/[0.08] text-[10px] font-semibold tabular-nums"
                  style={{ color: INK_SOFT, boxShadow: '0 0 0 2px rgb(20 20 22)' }}
