                it with the name field already waiting. */}
            <span className="shrink-0" onClick={(e) => e.stopPropagation()} onKeyDown={(e) => e.stopPropagation()}>
              <Button label="add preacher" icon={<PlusIcon size={11} />} onClick={onAdd} />
            </span>
          </div>
        </div>
      </div>}
    </Panel>
  );
}

