function Gates({ p }: { p: Preacher }) {
  const gates = p.gates ?? GATES;
  const rows = [
    { label: 'trust floor', now: p.trustLowerBound, need: gates.trust, fmt: pct },
    { label: 'verified detections', now: p.samples, need: gates.samples, fmt: (v: number) => String(v) },
