              </span>
            </p>
            <span className="block h-[4px] rounded-full bg-white/[0.06]">
              <span className="block h-full rounded-full" style={{ width: pct(frac), background: met ? MINT : GOLD }} />
            </span>
          </div>
        );
      })}
    </div>
  );
}

