export function MinuteScale({ y }: { y: number }) {
  return (
    <>
      {Array.from({ length: 25 }, (_, i) => {
        const major = i % 5 === 0;
        return (
          <line
            key={i}
            x1={8 + i * 5.583}
            y1={y}
            x2={8 + i * 5.583}
            y2={y + (major ? 5 : 2.5)}
            strokeOpacity={major ? 0.32 : 0.15}
          />
        );
      })}
    </>
  );
}

