function QuickSlideModal({ isOpen, onClose, onCreate, editing = null }: QuickSlideModalProps) {
  const [title, setTitle] = useState('');
  const [subtitle, setSubtitle] = useState('');
  const [bodyText, setBodyText] = useState('');
  const [align, setAlign] = useState<'left' | 'center' | 'right'>('center');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const nameOnly = !!editing && (!!editing.paths || editing.pages > 1);

  const titleRef = useRef<HTMLInputElement>(null);
  /* Each open starts clean, or on the slide being edited. */
  useEffect(() => {
    if (!isOpen) return;
    setTitle(nameOnly ? editing!.title : editing?.spec.title ?? '');
    setError(null);
    setSubtitle(editing?.spec.subtitle ?? '');
    setBodyText(editing?.spec.sections.flatMap((section) => section.bullets).join('\n') ?? '');
    setAlign('center');
    /* The caret goes to the title once the box has landed. */
    const t = setTimeout(() => titleRef.current?.focus(), 380);
    return () => clearTimeout(t);
  }, [isOpen]);

  const handleCreate = async () => {
    if (!title.trim() || saving) return;
    const bullets = bodyText
      .split('\n')
      .map((l) => l.trim())
      .filter(Boolean);

    const newDeck: Deck = nameOnly ? {
      ...editing!,
      title: title.trim(),
      spec: { ...editing!.spec, title: editing!.paths ? editing!.spec.title : title.trim() },
    } : {
      title: title.trim(),
      pages: 1,
      rendered: 1,
      excerpt: subtitle.trim() || 'quick presentation slide',
      sample: [title.trim(), subtitle.trim()].filter(Boolean),
      spec: {
        title: title.trim(),
        subtitle: subtitle.trim() || undefined,
        sections: bullets.length > 0 ? [{ heading: '', bullets }] : [],
      },
    };

    setSaving(true);
    setError(null);
    try {
      await onCreate(newDeck);
      onClose();
    } catch (error) {
      setError(error instanceof Error ? error.message : 'Could not save this slide. Try again.');
    } finally {
      setSaving(false);
    }
  };

  const input =
    'tri-rounded-control w-full border-0 bg-[rgb(0_0_0_/_0.20)] px-3.5 text-[length:var(--tri-control-size)] text-[var(--tri-ink)] placeholder:text-[rgb(229_243_242_/_0.34)] focus:outline-none focus:shadow-[inset_0_0_0_var(--tri-border)_rgb(var(--tri-go-2)_/_0.45)]';

  /* The brand's own opening, fields and buttons — see songs/FlightPopup. */
  return (
    <FlightPopup
      open={isOpen}
      size={{ w: 520, h: 500 }}
      label={nameOnly ? 'edit presentation' : editing ? 'edit slide' : 'quick slide'}
      onRequestClose={() => { if (!saving) onClose(); }}
      header={
        <div>
          <h2 className="text-[20px] font-semibold tracking-tight text-[var(--tri-ink)]">{nameOnly ? 'edit presentation' : editing ? 'edit slide' : 'quick slide'}</h2>
          <p className="mt-1 text-[length:var(--tri-size-xs)] leading-relaxed text-[rgb(229_243_242_/_0.5)]">
            {nameOnly ? editing?.paths ? 'change the library name. to change the slide content, edit the original file and import it again.' : 'change the presentation name. all pages are kept.' : 'a title, a line under it, and a few points. it joins your decks as a one-page slide.'}
          </p>
        </div>
      }
      footer={
        <footer className="flex shrink-0 justify-end px-6 pb-5">
          <Button label={saving ? 'saving…' : nameOnly ? 'save presentation' : editing ? 'save slide' : 'create slide'} tone="go" icon={<SparkleIcon size={12} />} disabled={!title.trim() || saving} onClick={() => void handleCreate()} />
        </footer>
      }
    >
      <div className="flex min-h-0 flex-1 flex-col gap-3 overflow-y-auto px-6 pb-4 pt-4">
        <input ref={titleRef} value={title} onChange={(e) => setTitle(e.target.value)} placeholder="title — welcome to church" aria-label="slide title" className={cx(input, 'h-[var(--tri-field-h)] shrink-0')} />
        {!nameOnly && <>
        <input value={subtitle} onChange={(e) => setSubtitle(e.target.value)} placeholder="line under it (optional) — sunday service · 10:00" aria-label="subtitle" className={cx(input, 'h-[var(--tri-field-h)] shrink-0')} />
        <SegmentedControl
          label="alignment"
          size="sm"
          options={[
            { id: 'left', label: 'left' },
            { id: 'center', label: 'centre' },
            { id: 'right', label: 'right' },
          ]}
          value={align}
          onChange={setAlign}
        />
        <textarea
          value={bodyText}
          onChange={(e) => setBodyText(e.target.value)}
          placeholder="points or notes, one per line (optional)"
          aria-label="points"
          className={cx(input, 'min-h-[88px] flex-1 resize-none py-3 leading-[1.55]')}
        />
        </>}
        {error && <p role="alert" className="text-sm text-[var(--tri-ink)]">{error}</p>}
      </div>
    </FlightPopup>
  );
}

source:9f818ae24175:
export function SlidesBrowser() {
  const drag = useDrag();
  const projector = useProjector();
  const [query, setQuery] = useState('');
  const [importNote, setImportNote] = useState<string | null>(null);
  const [quickModalOpen, setQuickModalOpen] = useState(false);
  const [editingDeck, setEditingDeck] = useState<LoadedDeck | null>(null);
  const [customDecks, setCustomDecks] = useState<LoadedDeck[]>(() => {
    try {
      const raw = localStorage.getItem('trilorah_custom_presentation_decks');
      return raw ? JSON.parse(raw) : [];
    } catch {
      return [];
    }
  });

  const [importedDecks, setImportedDecks] = useState<LoadedDeck[]>([]);
  const [hiddenDecks, setHiddenDecks] = useState<string[]>(() => readTriLocal(HIDDEN_DECKS_KEY, []));
  useEffect(() => {
    const reload = () => setCustomDecks(readTriLocal<LoadedDeck[]>(TRI_DECKS_KEY, []));
    window.addEventListener(TRI_DECKS_EVENT, reload);
    return () => window.removeEventListener(TRI_DECKS_EVENT, reload);
  }, []);
  useEffect(() => {
    const reload = () => { void window.api?.loadPresentations().then(items => setImportedDecks(items.map(d => ({
      id: d.id, title: d.title, paths: d.slides, pages: d.slides.length, rendered: d.slides.length,
      seed: 0, excerpt: '', sample: [], spec: { title: d.title, sections: [] },
    })))).catch(() => setImportNote('Could not load presentations. Try reopening Slides.')); };
    reload();
    window.addEventListener('presentations-updated', reload);
    return () => window.removeEventListener('presentations-updated', reload);
  }, []);
  const allDecks = useMemo(() => [...importedDecks, ...customDecks, ...(isEmptyPreview ? [] : DECKS.filter(deck => !hiddenDecks.includes(deck.id) && !customDecks.some(custom => custom.id === deck.id)))], [importedDecks, customDecks, hiddenDecks]);

  const handleCreateQuickDeck = async (deck: Deck) => {
    if (editingDeck && importedDecks.some(item => item.id === editingDeck.id)) {
      if (!window.api?.loadPresentations || !window.api?.savePresentations) throw new Error('Editing this presentation needs the desktop app.');
      const current = await window.api.loadPresentations();
      const result = await window.api.savePresentations(current.map(item => item.id === editingDeck.id ? { ...item, title: deck.title } : item));
      if (!result?.success) throw new Error(result?.error || 'Could not save this presentation.');
      setImportedDecks(prev => prev.map(item => item.id === editingDeck.id ? { ...item, title: deck.title } : item));
      window.dispatchEvent(new Event('presentations-updated'));
      return;
    }
    const loaded: LoadedDeck = {
      ...deck,
      id: editingDeck?.id ?? `custom-deck-${Date.now()}`,
      seed: editingDeck?.seed ?? Math.floor(Math.random() * 100),
    };
    const updated = customDecks.some(item => item.id === loaded.id)
      ? customDecks.map(item => item.id === loaded.id ? loaded : item)
      : [loaded, ...customDecks];
    localStorage.setItem(TRI_DECKS_KEY, JSON.stringify(updated));
    setCustomDecks(updated);
    window.dispatchEvent(new Event('trilorah-library-changed'));
  };

  /* Off the shelf. An imported deck's page images are the app's own copies,
     so they go with it; a quick slide is only a line in local storage. */
  const removeDeck = async (deck: LoadedDeck) => {
    if (importedDecks.some(item => item.id === deck.id)) {
      try {
        const deleted = await window.api?.deletePresentation({ id: deck.id, slides: deck.paths });
        if (!deleted?.success) throw new Error(deleted?.error || 'Could not delete that presentation.');
        const remaining = ((await window.api?.loadPresentations()) ?? []).filter((d: { id: string }) => d.id !== deck.id);
        const saved = await window.api?.savePresentations(remaining);
        if (!saved?.success) throw new Error(saved?.error || 'Could not save the presentation library.');
      } catch (error) {
        setImportNote(error instanceof Error ? error.message : 'Could not delete that presentation.');
        return;
      }
      window.dispatchEvent(new Event('presentations-updated'));
      return;
    }
    try {
      if (DECKS.some(item => item.id === deck.id)) {
        const hidden = [...new Set([...hiddenDecks, deck.id])];
        localStorage.setItem(HIDDEN_DECKS_KEY, JSON.stringify(hidden));
        setHiddenDecks(hidden);
      }
      const updated = customDecks.filter(item => item.id !== deck.id);
      localStorage.setItem(TRI_DECKS_KEY, JSON.stringify(updated));
      setCustomDecks(updated);
    } catch {
      setImportNote('Could not save this deletion. Try again.');
      return;
    }
    window.dispatchEvent(new Event('trilorah-library-changed'));
  };

  /* Which page each card is showing, once paged off its first. Sparse and
     keyed by deck, exactly as the songs grid keeps its verses: filter the
     grid and come back, and the card is where it was left. */
  const [pageAt, setPageAt] = useState<Record<string, number>>({});
  useEffect(() => {
    const item = projector.preview;
    if (item?.deckId && item.deckIndex != null) setPageAt(current => ({ ...current, [item.deckId!]: item.deckIndex! }));
  }, [projector.preview]);
  const request = useLibraryNavigation(state => state.request);
  useEffect(() => {
    const item=request?.item;
    if (item?.source !== 'presentation' || !item.path) return;
    const deck=allDecks.find(deck=>deck.paths?.includes(item.path!));
    if (!deck?.paths) return;
    const page=deck.paths.indexOf(item.path);
    setQuery(''); setPageAt(current=>({...current,[deck.id]:page}));
    projector.stage({source:'presentation',id:`${deck.id}:${page}`,label:item.label,path:item.path,deckId:deck.id,deckIndex:page,deckPaths:deck.paths,title:deck.title,mediaKind:'photo',origin:'operator'});
    useLibraryNavigation.getState().consume();
  }, [request,allDecks]);
  const pageOf = (deck: LoadedDeck) => Math.min(pageAt[deck.id] ?? 0, Math.max(0, deck.rendered - 1));
  const stepPage = (deck: LoadedDeck, delta: -1 | 1) =>
    setPageAt((m) => {
      const cur = m[deck.id] ?? 0;
      const next = Math.min(deck.rendered - 1, Math.max(0, cur + delta));
      return next === cur ? m : { ...m, [deck.id]: next };
    });

  const searchRow = useRef<HTMLDivElement>(null);
  const [searchOpen, setSearchOpen] = useState(false);
  const importSlides = () => {
    setImportNote('importing…');
    void importAndSavePresentation().then(deck => {
      setImportNote(deck ? `Imported ${deck.slides.length} slides. Select the deck to preview.` : null);
    }).catch(error => setImportNote(error instanceof Error ? error.message : 'Import failed. Try another file.'));
  };

  const needle = query.trim().toLowerCase();
  const matches = useMemo(
    () =>
      allDecks.filter((d) => {
        if (needle === '') return true;
        const hay = [
          d.title,
          d.excerpt,
          ...d.sample,
          d.spec.title,
          d.spec.subtitle ?? '',
          ...d.spec.sections.flatMap((s) => [s.heading, ...s.bullets]),
        ]
          .join(' ')
          .toLowerCase();
        return hay.includes(needle);
      }),
    [needle, allDecks],
  );

  const sel = useLibrarySelection({
    items: matches,
    source: 'presentation',
    idOf: (d) => `${d.id}:${pageOf(d)}`,
    labelOf: (d) => `${d.title} — slide ${pageOf(d) + 1}`,
    contentOf: d => {
      const paths = d.paths ?? Array.from({ length: d.rendered }, (_, i) => deckPage(d.seed, i, d.spec));
      return { path: paths[pageOf(d)], deckPaths: paths, deckIndex: pageOf(d), deckId: d.id, title: d.title, mediaKind: 'photo', origin: 'operator' };
    },
    selectFirst: false,
  });

  return (
    <>
      <QuickSlideModal
        isOpen={quickModalOpen}
        editing={editingDeck}
        onClose={() => { setQuickModalOpen(false); setEditingDeck(null); }}
        onCreate={handleCreateQuickDeck}
      />
      <LibraryBrowser
        searchInset="var(--tri-card-gap)"
        gap={16}
        search={
          searchOpen || allDecks.length === 0 || importNote ? <div ref={searchRow} className="flex min-w-0 flex-1 items-center gap-3">
            {searchOpen || allDecks.length === 0 ? (
            <LibrarySearch disabled={allDecks.length === 0}>
            <SearchField
              value={query}
              onChange={setQuery}
              placeholder="type a deck name or anything written on a slide..."
            />
            </LibrarySearch>
            ) : null}
            {/* What the import said, where the "import slides" card used to
                say it. Only while there is something to say. */}
            {importNote ? (
              <span className="max-w-[45%] shrink-0 truncate text-[length:var(--tri-size-xs)] lowercase text-[var(--tri-ink-muted)]">
                {importNote}
              </span>
            ) : null}
          </div> : null
        }
        dock={
          <LibraryToolbar
            label="presentations"
            searchActions={[
              {
                id: 'search',
                label: 'search slides',
                disabled: allDecks.length === 0,
                text: 'search slides',
                icon: <SearchIcon size={13} />,
                active: searchOpen,
                onClick: () => {
                  setSearchOpen(!searchOpen);
                  if (searchOpen) setQuery('');
                  else requestAnimationFrame(() => searchRow.current?.querySelector('input')?.focus());
                },
              },
            ]}
            actions={[
              {
                id: 'import',
                label: window.api?.importPresentation ? 'import slides — pptx, ppt or odp' : 'importing slides needs the desktop app',
                text: 'import slides',
                icon: <ImportIcon size={13} />,
                disabled: !window.api?.importPresentation,
                onClick: importSlides,
              },
              {
                id: 'quick',
                label: 'quick slide — a title, a line under it, and where they sit',
                text: 'quick slide',
                icon: <PresentationIcon size={13} />,
                onClick: () => setQuickModalOpen(true),
              },
            ]}
          />
        }
      >
        <LibraryPane header={false}>
          {matches.length === 0 ? (
            <EmptyMark w={220} h={220} plain art={<PresentationEmptyArt />}
              line={allDecks.length === 0 ? 'no presentations yet' : 'nothing matches'}
              hint={allDecks.length === 0 ? 'import a deck or create your first slide' : 'try a different deck name or a line from a slide'}
              below={<div className="mt-4 flex gap-2">
                {allDecks.length === 0 ? <>
                  {window.api?.importPresentation && <Button label="import slides" icon={<ImportIcon size={14} />} onClick={importSlides} />}
                  <Button label="quick slide" tone="go" icon={<PresentationIcon size={14} />} onClick={() => setQuickModalOpen(true)} />
                </> : <Button label="clear search" onClick={() => setQuery('')} />}
              </div>}
            />
          ) : (
            <div ref={sel.listRef}>
              <div
                className="grid auto-rows-min grid-cols-4 gap-4 px-4 pb-1"
              >
              {matches.map((deck, i) => {
                const at = pageOf(deck);
                const ready = deck.rendered > 0;
                const live = sel.isLive(i);
                const selected = sel.preview === i;
                const preview = ready ? (deck.paths ? presentationImageSrc(deck.paths[at]) : deckPage(deck.seed, at, deck.spec)) : undefined;
                return (
                  <div
                    key={deck.id}
                    className="group/card relative pb-3 transition-transform duration-150 ease-out hover:-translate-y-[2px]"
                    style={{ boxShadow: 'inset 0 -1px 0 rgb(255 255 255 / 0.08)' }}
                  >
                    <SlideThumb
                      index={i}
                      label={deck.title}
                      dragProps={drag.bind(() => ({
                        source: 'presentation' as const,
                        label: `${deck.title} — slide ${at + 1}`,
                        preview,
                        path: deck.paths?.[at] ?? preview,
                        mediaKind: 'photo',
                      }))}
                      /* The real first page the moment there is one. Until
                         then the wash carries the words off the front of the
                         deck, as the song card carries its verse. */
                      preview={preview}
                      stanzas={ready ? undefined : [deck.sample]}
                      backdropStyle={BACKDROP_BY_CONTENT.presentation}
                      /* Only what exists can be paged to. A count of 34 over
                         a deck with one rendered page would put the operator
                         on an arrow that does nothing. */
                      pager={
                        deck.rendered > 1
                          ? {
                              at,
                              count: deck.rendered,
                              onStep: (delta) => stepPage(deck, delta),
                            }
                          : undefined
                      }
                      /* The count, held on the picture, for a card that has
                         no pager to hold it: this is a real file of a known
                         length whose pages are on their way. */
                      badge={ready ? undefined : `${deck.pages} slides`}
                      showCaption={false}
                      selected={selected}
                      live={live}
                      onSelect={() => { if (ready) sel.setPreview(i); }}
                      onSend={() => { if (ready) sel.send(i); }}
                    />

                    <div className="mt-2 flex items-center justify-between gap-2 px-0.5" title={deck.title}>
                      <p
                        className={cx(
                          'min-w-0 truncate text-[length:var(--tri-size-sm)] font-semibold leading-[1.25] transition-colors',
                          live
                            ? 'text-[var(--tri-accent-yellow)]'
                            : selected
                              ? 'text-[var(--tri-ink)]'
                              : 'text-[rgb(229_243_242_/_0.86)] group-hover/card:text-[var(--tri-ink)]',
                        )}
                      >
                        {deck.title}
                      </p>
                      <div className="flex shrink-0 items-center gap-1.5" onPointerDown={event => event.stopPropagation()}>
                        <button type="button" title={`edit ${deck.title}`} aria-label={`edit ${deck.title}`}
                          className={cx(surface({ shape: 'control', interactive: true }), toneClass(), 'grid size-7 place-items-center')}
                          onClick={event => { event.stopPropagation(); setEditingDeck(deck); setQuickModalOpen(true); }}>
                          <PencilIcon size={12} />
                        </button>
                        <button type="button" title={`delete ${deck.title}`} aria-label={`delete ${deck.title}`}
                          className={cx(surface({ tone: 'danger', shape: 'control', interactive: true }), toneClass('danger'), 'grid size-7 place-items-center')}
                          onClick={event => { event.stopPropagation(); void removeDeck(deck); }}>
                          <TrashIcon size={12} />
                        </button>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </LibraryPane>
    </LibraryBrowser>
  </>
);
}

