export function SettingRow({
  row,
  value,
  onChange,
  onAction,
  saved,
}: {
  row: Row;
  value: unknown;
  onChange: (next: unknown) => void;
  /** An `action` row's press. Undefined leaves the button inert. */
  onAction?: () => void;
  /**
   * This row's last write: true saved, false failed, undefined quiet.
   * A screen that accepts a change in silence is indistinguishable from
   * one that dropped it.
   */
  saved?: boolean;
}) {
  if (row.kind === 'note') {
    return (
      <p className="max-w-[560px] py-2 text-[length:var(--tri-size-xs)] leading-relaxed" style={{ color: MUTED }}>
        {row.text}
      </p>
    );
  }

  let control: ReactNode;
  let wide = false;
  switch (row.kind) {
    case 'toggle':
      control = <Toggle on={Boolean(value)} onChange={onChange} />;
      break;
    case 'number':
      control = (
        <span className="flex items-baseline gap-1.5">
          <input className={cx(FIELD, 'w-[88px] text-right tabular-nums')} inputMode="numeric" value={String(value)} onChange={(e) => onChange(Number(e.target.value) || 0)} />
          {row.unit && <span className="text-[length:var(--tri-size-eyebrow)] text-[rgb(229_243_242_/_0.4)]">{row.unit}</span>}
        </span>
      );
      break;
    case 'percent':
      control = (
        <span className="flex items-baseline gap-1.5">
          <input className={cx(FIELD, 'w-[64px] text-right tabular-nums')} inputMode="numeric" value={String(Math.round(Number(value) * 100))} onChange={(e) => onChange((Number(e.target.value) || 0) / 100)} />
          <span className="text-[length:var(--tri-size-eyebrow)] text-[rgb(229_243_242_/_0.4)]">%</span>
        </span>
      );
      break;
    case 'slider':
      control = (
        <span className="flex w-[280px] items-center gap-3">
          <Slider value={Number(value)} onChange={onChange} min={row.min} max={row.max} step={row.step} ticks={5} className="flex-1" />
          <span className="w-[40px] shrink-0 text-right tabular-nums text-[length:var(--tri-size)] text-[var(--tri-ink)]">
            {String(value)}
            <span className="text-[length:var(--tri-size-eyebrow)] text-[rgb(229_243_242_/_0.4)]">{row.unit}</span>
          </span>
        </span>
      );
      break;
    case 'text':
      control = <input className={cx(FIELD, 'w-[280px]')} value={String(value)} placeholder={row.placeholder} spellCheck={false} onChange={(e) => onChange(e.target.value)} />;
      break;
    case 'secret':
      control = row.key === 'pixabayApiKey' || row.key === 'pexelsApiKey' || row.key === 'youtubeApiKey' ? <StockCredential settingKey={row.key} /> : <Secret set={row.set} />;
      break;
    case 'select': {
      const options = row.options.map((o) => (typeof o === 'string' ? { value: o, label: o } : o));
      /* Named options are proper names — a Bible is "KJV · King James
         Version", not "kjv · king james version" — so they keep their
         capitals, and get the text field's width in a box of their own
         (the Select's own w-full would otherwise shrink to the row's
         120px floor and wrap every name onto two lines). */
      control = row.options.some((o) => typeof o !== 'string')
        ? <div className="w-[280px]"><Select value={String(value)} options={options} onChange={onChange} preserveCase menuMinWidth={280} /></div>
        : <Select value={String(value)} options={options} onChange={onChange} className="w-[200px]" />;
      break;
    }
    case 'segment':
      control = <SegmentedControl size="sm" value={String(value)} options={row.options.map((o) => ({ id: o, label: o }))} onChange={onChange} className="w-[260px]" />;
      break;
    case 'action':
      control = (
        <span className="flex items-center gap-3">
          {row.note && <span className="whitespace-nowrap text-[length:var(--tri-size-xs)]" style={{ color: MUTED }}>{row.note}</span>}
          {/* No handler → disabled rather than dead. A button that looks
              pressable and does nothing is how "sign in" sat on the
              Connected tile doing nothing at all. */}
          <Button label={row.button} tone={row.tone} onClick={onAction} disabled={!onAction} />
        </span>
      );
      break;
    case 'status':
      control = <StatusLine state={row.state} text={row.text} />;
      break;
    case 'keys':
      control = <KeyList keys={row.keys} />;
      wide = true;
      break;
    case 'displays':
      control = <DisplayMap displays={row.displays} />;
      wide = true;
      break;
    case 'fonts':
      control = <FontChooser value={String(value)} faces={row.faces} onChange={onChange} />;
      wide = true;
      break;
  }

  return (
    <div data-guide={`setting-${row.key}`} className={cx('py-4', wide ? 'flex flex-col gap-4' : 'flex items-center gap-8')} style={{ boxShadow: 'inset 0 -1px 0 rgb(255 255 255 / 0.06)' }}>
      <div className="min-w-0 flex-1">
        <div className="text-[length:var(--tri-size)] font-semibold text-[var(--tri-ink)]">{row.label}</div>
        {row.blurb && (
          <p className="mt-1 max-w-[520px] text-[length:var(--tri-size-xs)] leading-relaxed text-[rgb(229_243_242_/_0.5)]">{row.blurb}</p>
        )}
      </div>
      <div className={cx('flex items-center gap-2.5', wide ? 'justify-start' : 'shrink-0 justify-end')} style={wide ? undefined : { minWidth: 120 }}>
        {control}
        {saved !== undefined && (
          <span
            className="inline-flex items-center gap-1 whitespace-nowrap text-[length:var(--tri-size-eyebrow)] lowercase"
            style={{ color: saved ? '#8fd3c0' : '#eac7c6' }}
          >
            {saved && <CheckIcon size={10} />}
            {saved ? 'saved' : 'not saved'}
          </span>
        )}
      </div>
    </div>
  );
}

