function CardAction({
  label,
  text,
  onClick,
  disabled = false,
  danger = false,
  children,
}: {
  label: string;
  text?: string;
  onClick: () => void;
  disabled?: boolean;
  danger?: boolean;
  children: React.ReactNode;
}) {
  return (
    <button
      type="button"
      title={label}
      aria-label={label}
      disabled={disabled}
      onClick={onClick}
      className={cx('song-editor-action', text && 'song-editor-action--labelled', danger && 'song-editor-action--danger')}
    >
      {children}{text ? <span>{text}</span> : null}
    </button>
  );
}

