export function LiveHost() {
  const ref = useRef<HTMLDivElement>(null);
  const [size, setSize] = useState<ArtboardSize | null>({ id: 'window', label: 'window', w: 1440, h: 900, tier: tierForWidth(1440), note: 'the app window', full: true });

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const measure = () => {
      const w = Math.round(el.clientWidth);
      const h = Math.round(el.clientHeight);
      if (!w || !h) return;
      setSize((prev) =>
        prev && prev.w === w && prev.h === h
          ? prev
          : { id: 'window', label: 'window', w, h, tier: tierForWidth(w), note: 'the app window', full: true },
      );
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  return (
    <div ref={ref} className="h-full w-full min-w-0 overflow-hidden">
      {size && (
        <ArtboardProvider value={size}>
          <LiveScreen />
        </ArtboardProvider>
      )}
    </div>
  );
}

