export function Notes() {
  const notesSnapshot = useLiveStore((s) => s.notesSnapshot);
  const generatedNotes = useLiveStore((s) => s.generatedNotes);
  const setGeneratedNotes = useLiveStore((s) => s.setGeneratedNotes);
  const [busy, setBusy] = useState(false);
  const [note, setNote] = useState<string | null>(null);

  const exportable: SermonNotes | null =
    generatedNotes ?? (notesSnapshot ? snapshotToNotes(notesSnapshot) : null);

  const generate = async () => {
    setBusy(true);
    setNote(null);
    try {
      const notes = await window.api?.generateSermonNotes();
      if (notes) setGeneratedNotes(notes);
      else setNote('no notes came back — is a sermon transcript available?');
    } catch {
      setNote('could not generate notes');
    } finally {
      setBusy(false);
    }
  };

  const exportAs = async (kind: 'pdf' | 'md') => {
    if (!exportable) return;
    setNote(null);
    try {
      const res =
        kind === 'pdf'
          ? await window.api?.exportSermonNotesPdf(exportable)
          : await window.api?.exportSermonNotesMd(exportable);
      if (res?.success) setNote(`exported${res.path ? ` — ${res.path}` : ''}`);
      else if (res?.error) setNote(res.error);
    } catch {
      setNote('export failed');
    }
  };

  return (
    <div className="space-y-6">
      <div className="space-y-1">
        <h2 className="text-xl font-semibold tracking-tight">Notes</h2>
        <p className="text-sm text-neutral-500">
          The engine outlines the sermon as it's preached — polish it into shareable notes when the
          service ends.
        </p>
        {!hasEngine() && <EngineNote />}
      </div>

      <Panel>
        <PanelHeader>live outline</PanelHeader>
        {notesSnapshot ? (
          <LiveOutline snapshot={notesSnapshot} />
        ) : hasEngine() ? (
          <EmptyState>the engine builds this outline while the sermon is preached</EmptyState>
        ) : (
          <EngineNote />
        )}
      </Panel>

      <Panel>
        <PanelHeader>sermon notes</PanelHeader>
        <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
          <Button label="Generate notes" variant="solid" onClick={() => void generate()} disabled={!hasEngine() || busy} />
          <Button label="Export PDF" onClick={() => void exportAs('pdf')} disabled={!hasEngine() || !exportable} />
          <Button label="Export Markdown" onClick={() => void exportAs('md')} disabled={!hasEngine() || !exportable} />
        </div>
        {busy && <p className="mt-3 text-sm italic text-neutral-400">generating…</p>}
        {note && <p className="mt-3 text-sm text-neutral-500">{note}</p>}
        {generatedNotes && (
          <div className="mt-6 border-t border-hairline pt-6">
            <NotesDocument notes={generatedNotes} />
          </div>
        )}
      </Panel>
    </div>
  );
}

