    <button
      onClick={onClick}
      className="flex-1 flex flex-col items-center gap-1 py-3 rounded-xl bg-white/5 hover:bg-white/10 active:scale-[0.97] transition-all"
    >
      {icon}
      <span className="text-[11px] text-gray-400">{label}</span>
    </button>
  );
}

